// Read-only access to the product catalogue.
// products.json is generated by scripts/sync-prices.mjs (from the Google Sheet, or the saved copy).
// Do not edit prices in page components — change the sheet (or products.json) instead.

import catalog from "./products.json";
import birlaChetak from "../assets/birla-chetak.webp";
import perfectPlus from "../assets/perfect-plus.webp";
import iwpCement from "../assets/iwp-cement.webp";

// The sheet's "image" column refers to one of these keys.
// [url, width, height] — sizes let the browser reserve space before the image loads.
const PRODUCT_IMAGES = {
  "birla-chetak": [birlaChetak, 500, 380],
  "perfect-plus": [perfectPlus, 640, 640],
  "perfect-plus-iwp": [iwpCement, 640, 640],
};

const withImage = (p) => {
  const [imageUrl = null, imageWidth, imageHeight] = PRODUCT_IMAGES[p.image] ?? [];
  return { ...p, imageUrl, imageWidth, imageHeight };
};

export const products = catalog.products.map(withImage);

export const getProducts = (category) => products.filter((p) => p.category === category);

// Latest "updated_on" date among a set of products, or null if none is filled in.
export const latestUpdate = (items) =>
  items.reduce((latest, p) => (p.updatedOn && (!latest || p.updatedOn > latest) ? p.updatedOn : latest), null);

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

// Same output on the build server and in every browser (e.g. "10 Oct 2026").
export const formatDate = (iso) => {
  const [y, m, d] = iso.split("-").map(Number);
  return `${d} ${MONTHS.at(m - 1)} ${y}`;
};

export const formatRupees = (n) => `₹${Math.round(n).toLocaleString("en-IN")}`;

export const hasPrice = (p) => typeof p.price === "number";

export const gstLabel = (p) => (p.gstIncluded === true ? "incl. GST" : p.gstIncluded === false ? "+ GST" : "");

export const AVAILABILITY_LABELS = {
  in_stock: "Available",
  out_of_stock: "Out of stock",
  ask: "Ask for availability",
};

export const isOrderable = (p) => p.availability !== "out_of_stock";

// Indicative money value of one unit (a bar priced per kg uses its nominal weight).
export const unitPrice = (p) => {
  if (!hasPrice(p)) return null;
  return p.priceBasis === "kg" ? p.price * p.unitWeightKg : p.price;
};
